أدخل نفس البرنامج كما في الأسفل.
وحدة النقود المستخدمة في الدرس هي "codycoins".

console.log("Set of 2 coffees " + (250 * 2) + " codycoins");

أكمل السطر الثاني من البرنامج كما في الأسفل:

console.log("Set of 2 coffees " + (250 * 2) + " codycoins");


console.log("Set of 3 coffees " + (250 * 3) + " codycoins");
